package com.sih.hr.entity;
import com.sih.shared.tenant.TenantScopedEntity; import jakarta.persistence.*; import java.time.LocalDate; import lombok.*;
@Entity @Table(name="hr_staff", uniqueConstraints=@UniqueConstraint(columnNames={"tenantId","employeeNumber"})) @Getter @Setter public class StaffMember extends TenantScopedEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String employeeNumber; @Column(nullable=false) private String firstName; @Column(nullable=false) private String lastName; @Column(nullable=false) private String department; @Column(nullable=false) private String position; @Column(nullable=false) private String employmentStatus="ACTIVE"; private boolean clinicalStaff; private String email; @Column(nullable=false) private LocalDate hiredOn=LocalDate.now(); }
